/* tslint:disable */
/* eslint-disable */
export interface CycleRecord {
    id: number;
    date: string;
    flow: string;
    notes: string;
}

export interface DashboardState {
    has_records: boolean;
    avg_cycle: number;
    cycle_day: number | null;
    phase_name: string;
    care_tip: string;
    days_until_next: number | null;
    next_period_date: string | null;
    pms_start_date: string | null;
    ovulation_date: string | null;
    history: RecordViewItem[];
}

export interface RecordViewItem {
    id: number;
    date: string;
    flow: string;
    notes: string;
    interval_days: number | null;
}


export class CycleStore {
    free(): void;
    [Symbol.dispose](): void;
    add_record(id: bigint, date_str: string, flow: string, notes: string): string;
    delete_record(id: bigint): string;
    export_snapshot(): string;
    /**
     * Generates an RFC 5545 .ics file containing PMS/Period alerts + embedded JSON backup
     */
    generate_ics(): string;
    get_dashboard_state(today_str: string): any;
    /**
     * Restores full history from an .ics file generated by this app
     */
    import_from_ics(ics_content: string): string;
    constructor(raw_json?: string | null);
}

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
    readonly memory: WebAssembly.Memory;
    readonly __wbg_cyclestore_free: (a: number, b: number) => void;
    readonly cyclestore_add_record: (a: number, b: bigint, c: number, d: number, e: number, f: number, g: number, h: number) => [number, number, number, number];
    readonly cyclestore_delete_record: (a: number, b: bigint) => [number, number];
    readonly cyclestore_export_snapshot: (a: number) => [number, number, number, number];
    readonly cyclestore_generate_ics: (a: number) => [number, number, number, number];
    readonly cyclestore_get_dashboard_state: (a: number, b: number, c: number) => [number, number, number];
    readonly cyclestore_import_from_ics: (a: number, b: number, c: number) => [number, number, number, number];
    readonly cyclestore_new: (a: number, b: number) => number;
    readonly __wbindgen_malloc: (a: number, b: number) => number;
    readonly __wbindgen_realloc: (a: number, b: number, c: number, d: number) => number;
    readonly __wbindgen_free: (a: number, b: number, c: number) => void;
    readonly __wbindgen_externrefs: WebAssembly.Table;
    readonly __externref_table_dealloc: (a: number) => void;
    readonly __wbindgen_start: () => void;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
 * Instantiates the given `module`, which can either be bytes or
 * a precompiled `WebAssembly.Module`.
 *
 * @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
 *
 * @returns {InitOutput}
 */
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
 * If `module_or_path` is {RequestInfo} or {URL}, makes a request and
 * for everything else, calls `WebAssembly.instantiate` directly.
 *
 * @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
 *
 * @returns {Promise<InitOutput>}
 */
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
